<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Submit Excuse - <?= h(APP_NAME) ?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/styles.css"></head>
<body><main class="page"><header class="topbar"><div class="brand-lockup"><img class="brand-mark" src="assets/app-icon.svg" alt=""><div><div class="brand-kicker">Ministry of Youth &amp; Sports</div><div class="brand"><?= h(APP_NAME) ?></div></div></div><nav class="nav-links"><a href="index.php">Clock Screen</a><a href="admin.php">Admin Login</a></nav></header><section class="hero"><div class="panel public-excuse-panel"><?php if ($result !== null && $result['ok']): ?><div class="confirmation-screen"><div class="confirmation-label">Request Sent</div><h1>Your excuse was sent successfully.</h1><p>Human Resource will review your request and approve or deny it. Please keep your supporting documents available if they are needed.</p><a class="button primary full-button" href="index.php">Back to Clock Screen</a></div><?php else: ?><div class="admin-login-head"><span class="eyebrow">Employee Request</span><h1>Submit an Excuse</h1><p class="muted">Complete this form yourself. Human Resource will review and approve or deny your request.</p></div><?php if ($result !== null): ?><div class="alert error"><?= h($result['message']) ?></div><?php endif; ?><form method="post" class="row g-3" id="publicExcuseForm"><div class="col-12"><label class="form-label" for="employee_number">Employee number</label><input class="form-control" id="employee_number" name="employee_number" required autofocus autocomplete="off"><p class="muted mt-2 mb-0" id="employeeLookup" role="status">Enter your registered employee number.</p></div><div class="col-12 col-md-6"><label class="form-label" for="absence_start">Date of absence</label><input class="form-control" id="absence_start" name="absence_start" type="date" required></div><div class="col-12 col-md-6"><label class="form-label" for="absence_end">End date</label><input class="form-control" id="absence_end" name="absence_end" type="date" required></div><div class="col-12"><label class="form-label" for="absence_time">Time (only if partial absence)</label><input class="form-control" id="absence_time" name="absence_time" placeholder="Example: 10:00 AM - 1:00 PM"></div><div class="col-12"><label class="form-label" for="reason">Reason for excuse</label><select class="form-select" id="reason" name="reason" required><option value="">Select reason</option><option>Medical Appointment</option><option>Illness</option><option>Family Emergency</option><option>Official Assignment</option><option>Other</option></select></div><div class="col-12" id="otherReasonWrap" hidden><label class="form-label" for="other_reason">Other reason</label><input class="form-control" id="other_reason" name="other_reason"></div><div class="col-12"><button class="button primary full-button" id="submitExcuse" type="submit" disabled>Send Excuse Request</button></div></form><script>const employeeInput=document.getElementById('employee_number'), employeeLookup=document.getElementById('employeeLookup'), submitExcuse=document.getElementById('submitExcuse'); let lookupTimer; employeeInput.addEventListener('input',()=>{clearTimeout(lookupTimer); submitExcuse.disabled=true; employeeLookup.textContent='Checking employee number...'; lookupTimer=setTimeout(async()=>{const number=employeeInput.value.trim(); if(!number){employeeLookup.textContent='Enter your registered employee number.';return;} try{const response=await fetch('employee_lookup.php?employee_number='+encodeURIComponent(number));const employee=await response.json();if(employee.found){employeeLookup.textContent='Registered employee: '+employee.name+' ('+employee.department+')';submitExcuse.disabled=false;}else{employeeLookup.textContent='Employee number was not found. Please check it and try again.';}}catch{employeeLookup.textContent='Unable to verify employee number. Please try again.';}},250);});document.getElementById('reason').addEventListener('change', e => document.getElementById('otherReasonWrap').hidden = e.target.value !== 'Other');</script><?php endif; ?></div></section></main></body></html>
